import{_ as p,a0 as l,w as d,s as r,ao as o,I as t,a1 as e,A as i,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"BootISO：从 ISO 文件中创建一个可启动的 USB 设备 | LCTT x X-CMD","titleTemplate":false,"description":"BootISO：从 ISO 文件中创建一个可启动的 USB 设备 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"BootISO：从 ISO 文件中创建一个可启动的 USB 设备 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"BootISO：从 ISO 文件中创建一个可启动的 USB 设备 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20180604 BootISO - A Simple Bash Script To Securely Create A Bootable USB Device From ISO File","title":"BootISO：从 ISO 文件中创建一个可启动的 USB 设备","tag":"201906","desc":""},"relativePath":"201906/20180604 BootISO - A Simple Bash Script To Securely Create A Bootable USB Device From ISO File.md","filePath":"[post].md"}'),c={name:"201906/20180604 BootISO - A Simple Bash Script To Securely Create A Bootable USB Device From ISO File.md"};function h(u,s,b,g,S,m){const n=l("Link");return d(),r("div",null,[s[19]||(s[19]=o('<h1 id="bootiso-从-iso-文件中创建一个可启动的-usb-设备" tabindex="-1">BootISO：从 ISO 文件中创建一个可启动的 USB 设备 <a class="header-anchor" href="#bootiso-从-iso-文件中创建一个可启动的-usb-设备" aria-label="Permalink to “BootISO：从 ISO 文件中创建一个可启动的 USB 设备”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/16/110109qq0b7atyaped3ij2.jpg" alt=""></p><p>为了安装操作系统，我们中的大多数人（包括我）经常从 ISO 文件中创建一个可启动的 USB 设备。为达到这个目的，在 Linux 中有很多自由可用的应用程序。甚至在过去我们写了几篇介绍这种实用程序的文章。</p><p>每个人使用不同的应用程序，每个应用程序有它们自己的特色和功能。在这些应用程序中，一些应用程序属于 CLI 程序，一些应用程序则是 GUI 的。</p><p>今天，我们将讨论名为 BootISO 的实用程序类似工具。它是一个简单的 bash 脚本，允许用户来从 ISO 文件中创建一个可启动的 USB 设备。</p><p>很多 Linux 管理员使用 <code>dd</code> 命令开创建可启动的 ISO ，它是一个著名的原生方法，但是与此同时，它也是一个非常危险的命令。因此，小心，当你用 <code>dd</code> 命令执行一些动作时。</p><p>建议阅读：</p>',7)),t("ul",null,[t("li",null,[e(n,{href:"https://www.2daygeek.com/etcher-easy-way-to-create-a-bootable-usb-drive-sd-card-from-an-iso-image-on-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("Etcher：从一个 ISO 镜像中创建一个可启动的 USB 驱动器 & SD 卡的简单方法",-1)])]),_:1})]),t("li",null,[e(n,{href:"https://www.2daygeek.com/create-a-bootable-usb-drive-from-an-iso-image-using-dd-command-on-linux/"},{default:i(()=>[...s[1]||(s[1]=[a("在 Linux 上使用 dd 命令来从一个 ISO 镜像中创建一个可启动的 USB 驱动器",-1)])]),_:1})])]),s[20]||(s[20]=t("h3",{id:"bootiso-是什么",tabindex:"-1"},[a("BootISO 是什么 "),t("a",{class:"header-anchor",href:"#bootiso-是什么","aria-label":"Permalink to “BootISO 是什么”"},"​")],-1)),t("p",null,[e(n,{href:"https://github.com/jsamr/bootiso"},{default:i(()=>[...s[2]||(s[2]=[a("BootISO",-1)])]),_:1}),s[3]||(s[3]=a(" 是一个简单的 bash 脚本，允许用户来安全的从一个 ISO 文件中创建一个可启动的 USB 设备，它是用 bash 编写的。",-1))]),s[21]||(s[21]=o(`<p>它不提供任何图形用户界面而是提供了大量的选项，可以让初学者顺利地在 Linux 上来创建一个可启动的 USB 设备。因为它是一个智能工具，能自动地选择连接到系统上的 USB 设备。</p><p>当系统有多个 USB 设备连接，它将打印出列表。当你手动选择了另一个硬盘而不是 USB 时，在这种情况下，它将安全地退出，而不会在硬盘上写入任何东西。</p><p>这个脚本也将检查依赖关系，并提示用户安装，它可以与所有的软件包管理器一起工作，例如 apt-get、yum、dnf、pacman 和 zypper。</p><h3 id="bootiso-的功能" tabindex="-1">BootISO 的功能 <a class="header-anchor" href="#bootiso-的功能" aria-label="Permalink to “BootISO 的功能”">​</a></h3><ul><li>它检查选择的 ISO 是否是正确的 mime 类型。如果不是，那么退出。</li><li>如果你选择除 USB 设备以外的任何其它的磁盘（本地硬盘），BootISO 将自动地退出。</li><li>当你有多个驱动器时，BootISO 允许用户选择想要使用的 USB 驱动器。</li><li>在擦除和分区 USB 设备前，BootISO 会提示用户确认。</li><li>BootISO 将正确地处理来自一个命令的任何错误，并退出。</li><li>BootISO 在遇到问题退出时将调用一个清理例行程序。</li></ul><h3 id="如何在-linux-中安装-bootiso" tabindex="-1">如何在 Linux 中安装 BootISO <a class="header-anchor" href="#如何在-linux-中安装-bootiso" aria-label="Permalink to “如何在 Linux 中安装 BootISO”">​</a></h3><p>在 Linux 中安装 BootISO 有几个可用的方法，但是，我建议用户使用下面的方法安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -L https://git.io/bootiso -O</span></span>
<span class="line"><span>$ chmod +x bootiso</span></span>
<span class="line"><span>$ sudo mv bootiso /usr/local/bin/</span></span></code></pre></div><p>一旦 BootISO 已经安装，运行下面的命令来列出可用的 USB 设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE   TYPE</span></span>
<span class="line"><span>sdd  1       32G  running disk</span></span></code></pre></div><p>如果你仅有一个 USB 设备，那么简单地运行下面的命令来从一个 ISO 文件中创建一个可启动的 USB 设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso /path/to/iso file</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span>
<span class="line"><span>Granting root privileges for bootiso.</span></span>
<span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE   TYPE</span></span>
<span class="line"><span>sdd  1       32G  running disk</span></span>
<span class="line"><span>Autoselecting \`sdd&#39; (only USB device candidate)</span></span>
<span class="line"><span>The selected device \`/dev/sdd&#39; is connected through USB.</span></span>
<span class="line"><span>Created ISO mount point at \`/tmp/iso.vXo&#39;</span></span>
<span class="line"><span>\`bootiso&#39; is about to wipe out the content of device \`/dev/sdd&#39;.</span></span>
<span class="line"><span>Are you sure you want to proceed? (y/n)&gt;y</span></span>
<span class="line"><span>Erasing contents of /dev/sdd...</span></span>
<span class="line"><span>Creating FAT32 partition on \`/dev/sdd1&#39;...</span></span>
<span class="line"><span>Created USB device mount point at \`/tmp/usb.0j5&#39;</span></span>
<span class="line"><span>Copying files from ISO to USB device with \`rsync&#39; </span></span>
<span class="line"><span>Synchronizing writes on device \`/dev/sdd&#39; </span></span>
<span class="line"><span>\`bootiso&#39; took 250 seconds to write ISO to USB device with \`rsync&#39; method.</span></span>
<span class="line"><span>ISO succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully ejected.</span></span>
<span class="line"><span>You can safely remove it !</span></span></code></pre></div><p>当你有多个 USB 设备时，可以使用 <code>--device</code> 选项指明你的设备名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>默认情况下，BootISO 使用 <code>rsync</code> 命令来执行所有的动作，如果你想使用 <code>dd</code> 命令代替它，使用下面的格式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --dd -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>如果你想跳过 mime 类型检查，BootISO 实用程序带有下面的选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --no-mime-check -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>为 BootISO 添加下面的选项来跳过在擦除和分区 USB 设备前的用户确认。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>连同 <code>-y</code> 选项一起，启用自动选择 USB 设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y -a /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>为知道更多的 BootISO 选项，运行下面的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -h</span></span>
<span class="line"><span>Create a bootable USB from any ISO securely.</span></span>
<span class="line"><span>Usage: bootiso [...] </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-h, --help, help             Display this help message and exit.</span></span>
<span class="line"><span>-v, --version                Display version and exit.</span></span>
<span class="line"><span>-d, --device         Select  block file as USB device.</span></span>
<span class="line"><span>                             If  is not connected through USB, \`bootiso&#39; will fail and exit.</span></span>
<span class="line"><span>                             Device block files are usually situated in /dev/sXX or /dev/hXX.</span></span>
<span class="line"><span>                             You will be prompted to select a device if you don&#39;t use this option.</span></span>
<span class="line"><span>-b, --bootloader             Install a bootloader with syslinux (safe mode) for non-hybrid ISOs. Does not work with \`--dd&#39; option.</span></span>
<span class="line"><span>-y, --assume-yes             \`bootiso&#39; won&#39;t prompt the user for confirmation before erasing and partitioning USB device.</span></span>
<span class="line"><span>                             Use at your own risks.</span></span>
<span class="line"><span>-a, --autoselect             Enable autoselecting USB devices in conjunction with -y option.</span></span>
<span class="line"><span>                             Autoselect will automatically select a USB drive device if there is exactly one connected to the system.</span></span>
<span class="line"><span>                             Enabled by default when neither -d nor --no-usb-check options are given.</span></span>
<span class="line"><span>-J, --no-eject               Do not eject device after unmounting.</span></span>
<span class="line"><span>-l, --list-usb-drives        List available USB drives.</span></span>
<span class="line"><span>-M, --no-mime-check          \`bootiso&#39; won&#39;t assert that selected ISO file has the right mime-type.</span></span>
<span class="line"><span>-s, --strict-mime-check      Disallow loose application/octet-stream mime type in ISO file.</span></span>
<span class="line"><span>--                           POSIX end of options.</span></span>
<span class="line"><span>--dd                         Use \`dd&#39; utility instead of mounting + \`rsync&#39;.</span></span>
<span class="line"><span>                             Does not allow bootloader installation with syslinux.</span></span>
<span class="line"><span>--no-usb-check               \`bootiso&#39; won&#39;t assert that selected device is a USB (connected through USB bus).</span></span>
<span class="line"><span>                             Use at your own risks.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Readme</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Bootiso v2.5.2.</span></span>
<span class="line"><span>    Author: Jules Samuel Randolph</span></span>
<span class="line"><span>    Bugs and new features: https://github.com/jsamr/bootiso/issues</span></span>
<span class="line"><span>    If you like bootiso, please help the community by making it visible:</span></span>
<span class="line"><span>    * star the project at https://github.com/jsamr/bootiso</span></span>
<span class="line"><span>    * upvote those SE post: https://goo.gl/BNRmvm https://goo.gl/YDBvFe</span></span></code></pre></div><hr>`,26)),t("p",null,[s[5]||(s[5]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/bootiso-a-simple-bash-script-to-securely-create-a-bootable-usb-device-in-linux-from-iso-file/"},{default:i(()=>[...s[4]||(s[4]=[a("https://www.2daygeek.com/bootiso-a-simple-bash-script-to-securely-create-a-bootable-usb-device-in-linux-from-iso-file/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/prakash/"},{default:i(()=>[...s[6]||(s[6]=[a("Prakash Subramanian",-1)])]),_:1}),s[11]||(s[11]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),e(n,{href:"https://github.com/robsean"},{default:i(()=>[...s[8]||(s[8]=[a("robsean",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const B=p(c,[["render",h]]);export{y as __pageData,B as default};
